import os, subprocess, tempfile
writer = \"\"\"
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadCatalog, saveCatalog, setPinned } from './catalog/src/catalog.mjs';

const directory = process.argv[1];
const original = [
  { id: 'z', title: 'Зета', pinned: true },
  { id: 'a', title: 'Альфа', pinned: false },
  { id: 'b', title: 'Бета', pinned: true },
  { id: 'm', title: 'Мю', pinned: false },
];
for (const [scenario, target, pinned] of [
  ['pin', 'a', true],
  ['unpin', 'b', false],
]) {
  const path = join(directory, scenario + '.json');
  writeFileSync(path, JSON.stringify(original));
  const loaded = loadCatalog(path);
  assert.deepEqual(loaded, original);
  const changed = setPinned(loaded, target, pinned);
  const expected = original.map(card => card.id === target ? { ...card, pinned } : card);
  assert.deepEqual(changed, expected);
  saveCatalog(path, changed);
  console.log(JSON.stringify({ scenario, before: loaded, afterSet: changed }));
}
const legacyPath = join(directory, 'legacy.json');
writeFileSync(legacyPath, JSON.stringify([{ id: 'old', title: 'Старая' }, original[0]]));
assert.deepEqual(loadCatalog(legacyPath), [{ id: 'old', title: 'Старая', pinned: false }, original[0]]);
console.log('legacy: omitted pinned -> false, explicit true -> true');
const missingPath = join(directory, 'missing.json');
const input = JSON.stringify(original);
writeFileSync(missingPath, input);
for (const pinned of [true, false]) {
  const cards = loadCatalog(missingPath);
  assert.throws(() => setPinned(cards, 'missing', pinned), /Unknown card: missing/);
  assert.deepEqual(cards, original);
  assert.equal(readFileSync(missingPath, 'utf8'), input);
}
console.log('missing: both requested values throw Unknown card: missing; input and file unchanged');
\"\"\"
reader = \"\"\"
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadCatalog } from './catalog/src/catalog.mjs';

const directory = process.argv[1];
let failures = 0;
for (const [scenario, target, expected] of [
  ['pin', 'a', true],
  ['unpin', 'b', false],
]) {
  const path = join(directory, scenario + '.json');
  const stored = JSON.parse(readFileSync(path, 'utf8'));
  const reloaded = loadCatalog(path);
  const checks = {
    shape: () => assert.ok(stored.every(card => typeof card.pinned === 'boolean')),
    target: () => assert.equal(reloaded.find(card => card.id === target).pinned, expected),
    otherPinned: () => assert.equal(reloaded.find(card => card.id === 'z').pinned, true),
    otherUnpinned: () => assert.equal(reloaded.find(card => card.id === 'm').pinned, false),
    order: () => assert.deepEqual(reloaded.map(card => card.id), ['z', 'a', 'b', 'm']),
    titles: () => assert.deepEqual(reloaded.map(card => card.title), ['Зета', 'Альфа', 'Бета', 'Мю']),
  };
  console.log(JSON.stringify({ scenario, stored, reloaded }));
  for (const [name, check] of Object.entries(checks)) {
    try {
      check();
      console.log(scenario, name, 'PASS');
    } catch (error) {
      failures += 1;
      console.log(scenario, name, 'FAIL', error.actual, 'expected', error.expected);
    }
  }
}
process.exitCode = failures === 0 ? 0 : 1;
\"\"\"
with tempfile.TemporaryDirectory(prefix='.acceptance-data-', dir=os.getcwd()) as scratch:
    subprocess.run(['node', '--input-type=module', '-e', writer, scratch], check=True)
    result = subprocess.run(['node', '--input-type=module', '-e', reader, scratch])
raise SystemExit(result.returncode)
PY"

